    /** The wind on the post at tick [t], 0 to 1: mostly a breath, now and then a gust. */
    fun gust(t: Float): Float {
        val s = 0.5f + 0.3f * sin(0.043f * t) + 0.2f * sin(0.0171f * t + 1.1f)
        return 0.2f + 0.8f * s * s * s
